//! The reference's instructions for an agent running in T3 Code, as its
//! provider adapters send them: Claude Code's system prompt append
//! (`ClaudeAdapterV2`'s `systemPrompt.append`), Codex's turn context
//! (`buildCodexAdditionalContext`) and the text an ACP prompt carries. The text is the reference's
//! (`instructions.json`, generated by `scripts/update_agent_tools.py`), less
//! each line that names an agent tool this server does not serve yet, so an
//! agent is never told to reach for a tool it cannot call.
use serde_json::{json, Value};
use std::sync::LazyLock;

static INSTRUCTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("mcp_oauth/instructions.json")).expect("agent instructions")
});

fn text(key: &str) -> &'static str {
    INSTRUCTIONS[key].as_str().unwrap_or_default()
}

/// Whether `line` names one of `tools`: as a word, or through a wildcard such
/// as `preview_*` that covers it.
fn names_any(line: &str, tools: &[String]) -> bool {
    let word = |c: char| c.is_ascii_alphanumeric() || c == '_';
    tools.iter().any(|tool| {
        line.match_indices(tool.as_str()).any(|(at, _)| {
            let before = line[..at].chars().next_back();
            let after = line[at + tool.len()..].chars().next();
            !before.is_some_and(word) && !after.is_some_and(word)
        })
    }) || line.match_indices('*').any(|(at, _)| {
        let prefix: String = line[..at]
            .chars()
            .rev()
            .take_while(|c| word(*c))
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .collect();
        !prefix.is_empty() && tools.iter().any(|tool| tool.starts_with(&prefix))
    })
}

/// `text` less each line that names one of `unserved`, and each heading left
/// with nothing under it before the next heading (with the blank lines it
/// held). Text that names no unserved tool comes back unchanged.
pub(crate) fn without_unserved(text: &str, unserved: &[String]) -> String {
    let lines: Vec<&str> = text.split('\n').collect();
    let mut keep: Vec<bool> = lines
        .iter()
        .map(|line| !names_any(line, unserved))
        .collect();
    if keep.iter().all(|k| *k) {
        return text.to_owned();
    }
    let heading = |line: &str| line.starts_with('#');
    let mut index = 0;
    while index < lines.len() {
        if !heading(lines[index]) {
            index += 1;
            continue;
        }
        let end = (index + 1..lines.len())
            .find(|i| heading(lines[*i]))
            .unwrap_or(lines.len());
        let empty = (index + 1..end).all(|i| !keep[i] || lines[i].trim().is_empty());
        if empty && (index + 1..end).any(|i| !keep[i]) {
            for k in keep.iter_mut().take(end).skip(index) {
                *k = false;
            }
        }
        index = end;
    }
    lines
        .iter()
        .zip(keep)
        .filter_map(|(line, keep)| keep.then_some(*line))
        .collect::<Vec<_>>()
        .join("\n")
}

fn unserved() -> Vec<String> {
    crate::mcp_oauth::unserved_tool_names()
}

fn single_line(value: &str) -> String {
    value.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// `buildRuntimeInstructions`: the runtime sentence, then the pull request
/// linking text.
pub(crate) fn runtime(harness: &str, model: Option<&str>, effort: Option<&str>) -> String {
    without_unserved(
        &format!(
            "{}\n\n{}",
            runtime_info(harness, model, effort),
            text("pullRequestLinking")
        ),
        &unserved(),
    )
}

/// The pull request linking text alone, which a session's system prompt
/// carries for an agent that takes it there (Antigravity's
/// `_meta.antigravity.systemPrompt.append`).
pub(crate) fn pull_request_linking() -> String {
    without_unserved(text("pullRequestLinking"), &unserved())
}

/// The runtime sentence alone (`buildRuntimeInstructions` with
/// `pullRequestLinking: false`).
pub(crate) fn runtime_info(harness: &str, model: Option<&str>, effort: Option<&str>) -> String {
    let model = single_line(model.unwrap_or_default());
    let effort = single_line(effort.unwrap_or_default());
    let model_info = if !model.is_empty() && model != "auto" && model != "default" {
        format!(", as {model}")
    } else {
        String::new()
    };
    let effort_info = if effort.is_empty() {
        String::new()
    } else {
        format!(" with {effort} reasoning effort")
    };
    let info = format!(
        "{}{} harness{model_info}{effort_info}{}",
        text("runtimeInfoPrefix"),
        single_line(harness),
        text("runtimeInfoSuffix")
    );
    info
}

/// Claude Code's system prompt append: the runtime text, then, for a thread
/// with T3's MCP server, the orchestration text and Claude's own text about
/// background waits and `send_to_user`, then the device tool text (with its
/// ToolSearch line) for a thread that may use devices.
pub(crate) fn claude_append(has_mcp: bool, device: bool) -> String {
    let mut append = runtime("Claude Code", None, None);
    if has_mcp {
        let mut tools = format!(
            "{}{}{}",
            text("orchestration"),
            text("claudeBackgroundWait"),
            text("claudeSendToUser")
        );
        if device {
            tools.push_str(&format!("\n{}\n", text("deviceToolsWithToolSearch")));
        }
        append.push_str(&without_unserved(&tools, &unserved()));
    }
    append
}

/// An OpenCode 1.x prompt's `system` text, which every prompt of a turn
/// repeats (OpenCode runs each step with the latest user message's): for a
/// thread with T3's MCP server the orchestration text
/// (`t3OrchestrationSystemPrompt`, with the device tool text for a thread
/// that may use devices), then the runtime text naming the model's slug.
pub(crate) fn opencode_system(has_mcp: bool, device: bool, model: &str) -> String {
    let mut parts = Vec::new();
    if has_mcp {
        let orchestration = if device {
            format!("{}\n{}\n", text("orchestration"), text("deviceTools"))
        } else {
            text("orchestration").to_owned()
        };
        parts.push(without_unserved(&orchestration, &unserved()));
    }
    parts.push(runtime("OpenCode", Some(model), None));
    parts
        .into_iter()
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("\n\n")
}

/// The device tool text a Claude subagent starts with, as the reference's
/// `SubagentStart` hook adds it.
pub(crate) fn claude_subagent_device_context() -> String {
    without_unserved(text("deviceToolsWithToolSearch"), &unserved())
}

/// An ACP prompt's text with T3's instructions (`t3AcpPromptWithInstructions`):
/// ACP has no system or developer field, so they ride on the prompt, the
/// interaction mode's section first, then for a thread with T3's MCP server
/// the browser, device (when its credential may use them), orchestration and
/// terminal fallback text.
pub(crate) fn acp_prompt(
    prompt: &str,
    interaction_mode: &str,
    has_mcp: bool,
    has_device_tools: bool,
) -> String {
    let mode = if interaction_mode == "plan" {
        text("acpPlanMode")
    } else {
        text("acpDefaultMode")
    };
    let mut sections = vec![mode.to_owned()];
    if has_mcp {
        sections.push(text("browserTools").trim().to_owned());
        if has_device_tools {
            sections.push(text("deviceTools").to_owned());
        }
        sections.push(text("orchestration").trim().to_owned());
        sections.push(text("acpMcpFallback").to_owned());
    }
    let instructions = without_unserved(&sections.join("\n\n"), &unserved());
    format!(
        "<t3_code_instructions>\n{instructions}\n</t3_code_instructions>\n\n<user_request>\n{prompt}\n</user_request>"
    )
}

/// Codex's turn context for a thread with T3's MCP server: each
/// orchestration section, the runtime text, and the browser tool text (with
/// the device tool text for a thread that may use devices), each left out
/// when nothing of it remains.
pub(crate) fn codex_additional_context(model: &str, effort: Option<&str>, device: bool) -> Value {
    let unserved = unserved();
    let mut context = serde_json::Map::new();
    for (index, section) in INSTRUCTIONS["orchestrationSections"]
        .as_array()
        .into_iter()
        .flatten()
        .enumerate()
    {
        let value = without_unserved(section.as_str().unwrap_or_default(), &unserved);
        if !value.trim().is_empty() {
            context.insert(
                format!("t3_code_orchestration_{:02}", index + 1),
                json!({"kind": "application", "value": value}),
            );
        }
    }
    context.insert(
        "t3_code_runtime".into(),
        json!({"kind": "application", "value": runtime("Codex", Some(model), effort)}),
    );
    // `toolInstructions`: the browser text, then the device text for a
    // thread that may use devices.
    let mut tools = text("browserTools").to_owned();
    if device {
        tools = [tools.as_str(), text("deviceTools")]
            .into_iter()
            .filter(|part| !part.is_empty())
            .collect::<Vec<_>>()
            .join("\n\n");
    }
    let tools = without_unserved(&tools, &unserved);
    if !tools.trim().is_empty() {
        context.insert(
            "t3_code_tools".into(),
            json!({"kind": "application", "value": tools}),
        );
    }
    Value::Object(context)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_line_naming_an_unserved_tool_is_left_out_with_its_empty_heading() {
        let unserved = vec!["html_preview".to_owned(), "preview_status".to_owned()];
        let text = "## A\n\n- use `delegate_task`\n- call `html_preview`\n\n### B\n\n- `preview_*` only\n\n\n### C\n\nkeep";
        assert_eq!(
            without_unserved(text, &unserved),
            "## A\n\n- use `delegate_task`\n\n### C\n\nkeep"
        );
        // Text that names no unserved tool is the reference's, unchanged.
        let served = "\n\n## A\n\n- `delegate_task`\n";
        assert_eq!(without_unserved(served, &unserved), served);
        // A tool named inside a longer word is not that tool.
        assert_eq!(
            without_unserved("- html_previews", &unserved),
            "- html_previews"
        );
    }

    #[test]
    fn the_runtime_sentence_names_the_harness_model_and_effort() {
        let text = runtime("Codex", Some("gpt-5"), Some("high"));
        assert!(text.starts_with(
            "<runtime_info>In case you're asked: you are running in T3 Code through the Codex harness, as gpt-5 with high reasoning effort. No need"
        ));
        assert!(text.contains("<pull_request_linking>"));
        let plain = runtime("Claude Code", None, None);
        assert!(plain.contains("through the Claude Code harness. No need"));
        assert!(runtime("Codex", Some("default"), None).contains("Codex harness. No need"));
    }

    #[test]
    fn device_text_goes_only_to_threads_that_may_use_devices() {
        let devices = "## T3 Code devices";
        assert!(!claude_append(true, false).contains(devices));
        assert!(claude_append(true, true)
            .ends_with(&format!("\n{}\n", text("deviceToolsWithToolSearch"))));
        assert!(!claude_append(false, true).contains(devices));
        let tools =
            |device| codex_additional_context("m", None, device)["t3_code_tools"]["value"].clone();
        assert!(!tools(false).as_str().unwrap().contains(devices));
        assert_eq!(
            tools(true),
            json!(format!(
                "{}\n\n{}",
                text("browserTools"),
                text("deviceTools")
            ))
        );
        assert_eq!(
            claude_subagent_device_context(),
            text("deviceToolsWithToolSearch")
        );
    }

    #[test]
    fn served_instructions_name_only_served_tools() {
        let unserved = unserved();
        for text in [
            claude_append(true, true),
            codex_additional_context("m", None, true).to_string(),
        ] {
            for line in text.split('\n') {
                assert!(!names_any(line, &unserved), "{line}");
            }
        }
    }
}
